verify.cmd:
node -e 'const fs=require("fs")
const Q=String.fromCharCode(39)
const fail=(m)=>{console.error(m);process.exit(1)}
const S="test/e2e/surfaces.ts"
const D="test/e2e/__screenshots__/visual.spec.ts"
const src=(()=>{try{return fs.readFileSync(S,"utf8")}catch(e){return null}})()
if(src===null)fail(S+" is gone, so nothing declares how /nearby is photographed")
const row=src.split("\n").find(l=>l.includes("slug: "+Q+"app-nearby"+Q))
if(!row)fail("the /nearby surface row is gone; if it moved, retire this row against wherever it went rather than deleting the probe")
if(!/viewportOnly:\s*true/.test(row))fail("/nearby lost viewportOnly, so it is photographed whole again. Its height is not a function of its content -- a published Dispatch adds a row and the capture grows +119px at mobile and narrow, which fails on SIZE before a pixel is compared and which no mask can fix.")
const h=(n)=>{const b=fs.readFileSync(D+"/"+n).slice(16,24);return b.readUInt32BE(4)}
// POSITIVE CONTROL: a surface photographed WHOLE must be far taller than a viewport. If this
// reads viewport-sized, the reader is broken and every assertion below would pass vacuously.
let ctl
try{ctl=h("home--dawn-light-desktop.png")}catch(e){fail("POSITIVE CONTROL FAILED: cannot read a known full-page baseline, so the height reader proves nothing")}
if(ctl<=800)fail("POSITIVE CONTROL FAILED: a full-page baseline reads "+ctl+"px, not taller than a viewport, so this probe cannot tell viewport-sized from whole-page")
const want={desktop:800,mobile:844,narrow:568}
const bad=[]
for(const theme of ["light","dark"])for(const k of Object.keys(want)){
  const n="app-nearby--dawn-"+theme+"-"+k+".png"
  let got
  try{got=h(n)}catch(e){bad.push(n+" is missing");continue}
  if(got!==want[k])bad.push(n+" is "+got+"px, expected exactly "+want[k])
}
if(bad.length)fail("the /nearby baselines are not viewport-sized, so the flag is set but the committed pictures are still whole-page and pr-compare compares a viewport capture against them: "+bad.join("; "))
process.exit(0)'
